from typing import Dict, List, Tuple


class Gradebook:
    def __init__(self) -> None:
        # Stores assignment metadata: name -> (weight, kind)
        self._assignments: Dict[str, Tuple[float, str]] = {}
        # Stores student grades: student -> {assignment_name: grade}
        self._grades: Dict[str, Dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self._assignments[name] = (float(weight), kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the valid scale of 2.0 to 5.0.")

        if student not in self._grades:
            self._grades[student] = {}
        self._grades[student][assignment] = float(grade)

    def average(self, student: str) -> float:
        if not self._assignments:
            return 0.0

        student_grades = self._grades.get(student, {})

        # Collect quizzes to determine if any quiz needs to be dropped
        quizzes: List[Tuple[str, float, float]] = []  # (name, grade, weight)
        for name, (weight, kind) in self._assignments.items():
            if kind == "quiz":
                grade = student_grades.get(name, 2.0)
                quizzes.append((name, grade, weight))

        dropped_quiz_name = None
        if len(quizzes) > 1:
            # Find the quiz with the lowest grade.
            # In case of ties, any of the lowest can be dropped.
            lowest_quiz = min(quizzes, key=lambda q: q[1])
            dropped_quiz_name = lowest_quiz[0]

        total_weighted_sum = 0.0
        total_weight = 0.0

        for name, (weight, kind) in self._assignments.items():
            if name == dropped_quiz_name:
                continue

            grade = student_grades.get(name, 2.0)
            total_weighted_sum += grade * weight
            total_weight += weight

        if total_weight == 0.0:
            return 0.0

        return total_weighted_sum / total_weight
```

